package com.troday.api.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="moderation_actions") public class ModerationAction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="actor_user_id") private Long actorUserId; @Column(name="target_user_id") private Long targetUserId; @Column(name="target_post_id") private Long targetPostId; @Column(name="target_report_id") private Long targetReportId; private String action; @Lob private String reason; @Column(name="before_snapshot",columnDefinition="json") private String beforeSnapshot; @Column(name="after_snapshot",columnDefinition="json") private String afterSnapshot; @Column(name="occurred_at") private LocalDateTime occurredAt; public Long getId(){return id;} public Long getActorUserId(){return actorUserId;} public void setActorUserId(Long v){actorUserId=v;} public Long getTargetUserId(){return targetUserId;} public void setTargetUserId(Long v){targetUserId=v;} public Long getTargetPostId(){return targetPostId;} public void setTargetPostId(Long v){targetPostId=v;} public Long getTargetReportId(){return targetReportId;} public void setTargetReportId(Long v){targetReportId=v;} public String getAction(){return action;} public void setAction(String v){action=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public String getBeforeSnapshot(){return beforeSnapshot;} public void setBeforeSnapshot(String v){beforeSnapshot=v;} public String getAfterSnapshot(){return afterSnapshot;} public void setAfterSnapshot(String v){afterSnapshot=v;} public LocalDateTime getOccurredAt(){return occurredAt;} public void setOccurredAt(LocalDateTime v){occurredAt=v;} }
